problem.solution:
class Main {
    public static void main(String[] args) {
        // 첫 값을 읽고 종료값인지 확인해요.
        var scanner = new java.util.Scanner(System.in, "UTF-8");
        int value = scanner.nextInt();
        int sum = 0;
        // 0은 더하지 않고 종료 신호로 사용해요.
        while (value != 0) {
            sum += value;
            // 다음 입력을 읽어 조건이 바뀌게 해요.
            value = scanner.nextInt();
        }
        System.out.println(sum);
    }
}

