                            bounds[1] = positions.getEndPosition(tree, node.getInitializer());
                        } else {
                            // Java fields without an initializer have a defined default.
                            bounds[0] = positions.getEndPosition(tree, node) - 1;
                            bounds[1] = bounds[0];
